<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{api}from'../api/admin';const router=useRouter(),rows=ref<any[]>([]),loading=ref(false),visible=ref(false),editing=ref<any>(null);const filters=reactive({keyword:'',type:'',status:''});const form=reactive<any>({name:'',phone:'',contactMethod:'',customerType:'DIRECT',channelId:null,intendedPlan:'',requirementSummary:'',currentStatus:'待处理'});async function load(){loading.value=true;try{rows.value=await api.customers(filters)as any[]}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}function open(row?:any){editing.value=row||null;Object.assign(form,row||{name:'',phone:'',contactMethod:'',customerType:'DIRECT',channelId:null,intendedPlan:'',requirementSummary:'',currentStatus:'待处理'});visible.value=true}async function save(){try{editing.value?await api.updateCustomer(editing.value.id,form):await api.createCustomer(form);ElMessage.success('客户已保存');visible.value=false;load()}catch(e:any){ElMessage.error(e.message)}}onMounted(load);</script>
<template><div class="page"><div class="page-heading"><div><h1>客户管理</h1><p>客户档案是渠道、订单、ICCID 与对账数据的关联入口。</p></div><el-button type="primary" @click="open()">新增客户</el-button></div><div class="filter-bar"><el-input v-model="filters.keyword" placeholder="姓名或手机号" clearable/><el-select v-model="filters.type" placeholder="客户类型" clearable><el-option label="自营客户" value="DIRECT"/><el-option label="渠道客户" value="CHANNEL"/></el-select><el-input v-model="filters.status" placeholder="当前状态" clearable/><el-button @click="load">查询</el-button></div><div class="table-card"><div class="table-toolbar"><span class="table-title">客户档案</span><span class="table-meta">共 {{rows.length}} 位客户</span></div><el-table :data="rows" v-loading="loading"><el-table-column prop="name" label="客户姓名" min-width="120"/><el-table-column prop="phone" label="手机号" min-width="140"/><el-table-column prop="contactMethod" label="联系方式" min-width="140"/><el-table-column label="客户类型" width="110"><template #default="s">{{s.row.customerType==='CHANNEL'?'渠道客户':'自营客户'}}</template></el-table-column><el-table-column prop="channelId" label="渠道ID" width="100"/><el-table-column prop="intendedPlan" label="意向套餐" min-width="160"/><el-table-column prop="currentStatus" label="当前状态" width="120"/><el-table-column prop="createdAt" label="创建时间" min-width="165"/><el-table-column label="操作" fixed="right" width="150"><template #default="s"><el-button link type="primary" @click="router.push(`/customers/${s.row.id}`)">详情</el-button><el-button link @click="open(s.row)">编辑</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" :title="editing?'编辑客户':'新增客户'" width="680"><el-form label-position="top" class="customer-form"><el-row :gutter="18"><el-col :span="12"><el-form-item label="客户姓名"><el-input v-model="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="手机号"><el-input v-model="form.phone"/></el-form-item></el-col><el-col :span="12"><el-form-item label="联系方式"><el-input v-model="form.contactMethod" placeholder="企业微信 / Email"/></el-form-item></el-col><el-col :span="12"><el-form-item label="客户类型"><el-select v-model="form.customerType" style="width:100%"><el-option label="自营客户" value="DIRECT"/><el-option label="渠道客户" value="CHANNEL"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="渠道ID"><el-input-number v-model="form.channelId" :min="1" style="width:100%"/></el-form-item></el-col><el-col :span="12"><el-form-item label="当前状态"><el-input v-model="form.currentStatus"/></el-form-item></el-col><el-col :span="24"><el-form-item label="意向套餐"><el-input v-model="form.intendedPlan"/></el-form-item></el-col><el-col :span="24"><el-form-item label="需求摘要"><el-input v-model="form.requirementSummary" type="textarea" :rows="3"/></el-form-item></el-col></el-row></el-form><template #footer><div class="dialog-footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></div></template></el-dialog></div></template>

